// DequantBias AscendC kernel
// Multi-input fusion: int32 dequant + weight_scale + optional bias + optional activate_scale.
// 6 conditional branches handled via branchType and host-side identity tensors.

#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 1;

__aicore__ inline uint32_t CeilDivU32(uint32_t a, uint32_t b)
{
    if (b == 0U) { return 0U; }
    return (a + b - 1U) / bU;
}

// =========================================================================
// Data movement helpers
// =========================================================================

template <typename T>
__aicore__ inline void LoadGmToUb(
    AscendC::LocalTensor<T> &dst,
    AscendC::GlobalTensor<T> src,
    uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPadExtParams<T> padParams{true, 0, 0, static_cast<T>(0)};
    AscendC::DataCopyPad(dst, src, copyParams, padParams);
}

template <typename T>
__aicore__ inline void StoreUbToGm(
    AscendC::GlobalTensor<T> dst,
    AscendC::LocalTensor<T> &src,
    uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPad(dst, src, copyParams);
}

// =========================================================================
// Type helpers for Cast/dup
// =========================================================================

template <typename T>
__aicore__ inline AscendC::RoundMode OutputRoundModeHelper()
{
    if constexpr (std::is_same_v<T, bfloat16_t>) {
        return AscendC::RoundMode::CAST_ROUND;
    }
    return AscendC::RoundMode::CAST_NONE;
}

template <typename T>
__aicore__ inline void PrepareFp32Tensor(
    AscendC::LocalTensor<float> &dst,
    AscendC::LocalTensor<T> &src,
    AscendC::TBuf<AscendC::TPosition::VECCALC> &castBuf,
    int32_t count)
{
    if constexpr (std::is_same_v<T, float>) {
        dst = src.template ReinterpretCast<float>();
    } else {
        dst = castBuf.Get<float>();
        AscendC::Cast(dst, src, AscendC::RoundMode::CAST_NONE, count);
        AscendC::PipeBarrier<PIPE_V>();
    }
}

// =========================================================================
// Main kernel class
// =========================================================================
// T  = weight_scale dtype (half/float/bfloat16_t)
// OutT = output dtype (half/bfloat16_t)

template <typename T, typename OutT>
class DequantBiasKernel {
public:
    __aicore__ inline void Init(
        GM_ADDR x_gm, GM_ADDR ws_gm, GM_ADDR as_gm, GM_ADDR bias_gm, GM_ADDR y_gm,
        int32_t M, int32_t N, int32_t tileM, int32_t totalLength,
        int32_t branchType)
    {
        this->M = M;
        this->N = N;
        this->tileM = tileM;
        this->totalLength = totalLength;
        this->branchType = branchType;
        tileElems_ = tileM * N;

        xGM_.SetGlobalBuffer(reinterpret_cast<__gm__ int32_t *>(x_gm), static_cast<uint64_t>(M) * N);
        wsGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(ws_gm), N);
        asGM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(as_gm), M);
        biasGM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(bias_gm), N);
        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ OutT *>(y_gm), static_cast<uint64_t>(M) * N);

        if ASCEND_IS_AIV { InitAivBuffers(); }
    }

    __aicore__ inline void InitAivBuffers()
    {
        // --- TQue buffers (double buffered) ---
        pipe.InitBuffer(xInQueue_, BUFFER_NUM, tileElems_ * sizeof(int32_t));
        pipe.InitBuffer(yOutQueue_, BUFFER_NUM, tileElems_ * sizeof(OutT));

        // --- TBuf: resident buffers (loaded once) ---
        pipe.InitBuffer(wsBuf_, N * sizeof(T));
        pipe.InitBuffer(wsTileBuf_, tileElems_ * sizeof(float));
        pipe.InitBuffer(wsBroadcastTmpBuf_, 2 * tileElems_ * sizeof(uint8_t));
        pipe.InitBuffer(biasBuf_, N * sizeof(float));
        pipe.InitBuffer(biasTileBuf_, tileElems_ * sizeof(float));
        pipe.InitBuffer(biasBroadcastTmpBuf_, 2 * tileElems_ * sizeof(uint8_t));

        // --- TBuf: per-tile buffers ---
        pipe.InitBuffer(asBuf_, tileM * sizeof(float));
        pipe.InitBuffer(asTileBuf_, tileElems_ * sizeof(float));
        pipe.InitBuffer(asBroadcastTmpBuf_, 2 * tileElems_ * sizeof(uint8_t));
        pipe.InitBuffer(xFp32Buf_, tileElems_ * sizeof(float));
        pipe.InitBuffer(resultBuf_, tileElems_ * sizeof(float));
        pipe.InitBuffer(tmpBuf_, tileElems_ * sizeof(float));

        // --- Cast buffers ---
        if constexpr (!std::is_same_v<T, float>) {
            pipe.InitBuffer(wsCastBuf_, N * sizeof(float));
        }
        pipe.InitBuffer(xCastBuf_, tileElems_ * sizeof(float));
        if constexpr (!std::is_same_v<OutT, float>) {
            pipe.InitBuffer(yCastBuf_, tileElems_ * sizeof(float));
        }

        // --- Load resident weight_scale, cast to fp32, broadcast to 2D ---
        {
            wsInLocal_ = wsBuf_.Get<T>();
            LoadGmToUb(wsInLocal_, wsGM_, static_cast<uint32_t>(N));
            AscendC::PipeBarrier<PIPE_MTE2>();
            AscendC::PipeBarrier<PIPE_ALL>();

            auto ws1dLocal = wsInLocal_;
            if constexpr (std::is_same_v<T, float>) {
                ws1dFp32_ = ws1dLocal.template ReinterpretCast<float>();
            } else {
                auto wsCastLocal = wsCastBuf_.Get<float>();
                AscendC::Cast(wsCastLocal, ws1dLocal, AscendC::RoundMode::CAST_NONE, N);
                AscendC::PipeBarrier<PIPE_V>();
                ws1dFp32_ = wsCastLocal;
            }

            wsTileLocal_ = wsTileBuf_.Get<float>();
            wsBroadcastTmpLocal_ = wsBroadcastTmpBuf_.Get<uint8_t>();
            const uint32_t wsSrcShape[2] = {1U, static_cast<uint32_t>(N)};
            const uint32_t wsDstShape[2] = {static_cast<uint32_t>(tileM), static_cast<uint32_t>(N)};
            AscendC::PipeBarrier<PIPE_ALL>();
            AscendC::Broadcast<float, 2, 0>(
                wsTileLocal_, ws1dFp32_, wsDstShape, wsSrcShape, wsBroadcastTmpLocal_);
            AscendC::PipeBarrier<PIPE_V>();
        }

        // --- Load resident bias, broadcast to 2D ---
        {
            biasInLocal_ = biasBuf_.Get<float>();
            LoadGmToUb(biasInLocal_, biasGM_, static_cast<uint32_t>(N));
            AscendC::PipeBarrier<PIPE_MTE2>();
            AscendC::PipeBarrier<PIPE_ALL>();

            biasTileLocal_ = biasTileBuf_.Get<float>();
            biasBroadcastTmpLocal_ = biasBroadcastTmpBuf_.Get<uint8_t>();
            const uint32_t biasSrcShape[2] = {1U, static_cast<uint32_t>(N)};
            const uint32_t biasDstShape[2] = {static_cast<uint32_t>(tileM), static_cast<uint32_t>(N)};
            AscendC::PipeBarrier<PIPE_ALL>();
            AscendC::Broadcast<float, 2, 0>(
                biasTileLocal_, biasInLocal_, biasDstShape, biasSrcShape, biasBroadcastTmpLocal_);
            AscendC::PipeBarrier<PIPE_V>();
        }
    }

    __aicore__ inline void Process()
    {
        if ASCEND_IS_AIV {
            const int coreIdx = AscendC::GetBlockIdx();
            for (int32_t tileIdx = coreIdx; tileIdx < totalLength; tileIdx += AscendC::GetBlockNum()) {
                int32_t rowStart = tileIdx * tileM;
                int32_t validRows = M - rowStart;
                if (validRows > tileM) validRows = tileM;
                if (validRows <= 0) continue;
                ProcessTile(rowStart, validRows);
            }
        }
    }

private:
    // =====================================================================
    // CopyIn: load x[tileM, N] int32 from GM
    // =====================================================================
    __aicore__ inline void CopyInX(int32_t rowStart, int32_t tileSize)
    {
        xInLocal_ = xInQueue_.AllocTensor<int32_t>();
        LoadGmToUb(xInLocal_, xGM_[static_cast<uint64_t>(rowStart) * N], static_cast<uint32_t>(tileSize));
        xInQueue_.EnQue(xInLocal_);
    }

    // =====================================================================
    // Compute: branch-dependent compute on UB tensors
    // =====================================================================
    __aicore__ inline void Compute(int32_t rowStart, int32_t validRows)
    {
        const int32_t tileSize = validRows * N;

        // Allocate output buffer
        yOutLocal_ = yOutQueue_.AllocTensor<OutT>();
        if constexpr (std::is_same_v<OutT, float>) {
            yFp32Local_ = yOutLocal_.template ReinterpretCast<float>();
        } else {
            yFp32Local_ = yCastBuf_.Get<float>();
        }

        // Get per-tile buffers
        auto as1dLocal = asBuf_.Get<float>();
        auto asTileLocal = asTileBuf_.Get<float>();
        auto asBroadcastTmpLocal = asBroadcastTmpBuf_.Get<uint8_t>();
        auto xFp32Local = xFp32Buf_.Get<float>();
        auto resultLocal = resultBuf_.Get<float>();
        auto tmpLocal = tmpBuf_.Get<float>();

        // DeQue input x
        xInLocal_ = xInQueue_.DeQue<int32_t>();

        // Cast int32 → fp32
        if constexpr (std::is_same_v<int32_t, float>) {
            // Unreachable; just to satisfy compiler
            xFp32Local = xInLocal_.template ReinterpretCast<float>();
        } else {
            auto xCastLocal = xCastBuf_.Get<float>();
            AscendC::Cast(xCastLocal, xInLocal_, AscendC::RoundMode::CAST_NONE, tileSize);
            AscendC::PipeBarrier<PIPE_V>();
            xFp32Local = xCastLocal;
        }
        // xFp32Local is valid after Cast+Barrier

        // Load and broadcast activate_scale [validRows] → [validRows, N]
        LoadGmToUb(as1dLocal, asGM_[rowStart], static_cast<uint32_t>(validRows));
        AscendC::PipeBarrier<PIPE_MTE2>();
        AscendC::PipeBarrier<PIPE_ALL>();

        const uint32_t asSrcShape[2] = {static_cast<uint32_t>(validRows), 1U};
        const uint32_t asDstShape[2] = {static_cast<uint32_t>(validRows), static_cast<uint32_t>(N)};
        AscendC::PipeBarrier<PIPE_ALL>();
        AscendC::Broadcast<float, 2, 1>(
            asTileLocal, as1dLocal, asDstShape, asSrcShape, asBroadcastTmpLocal);
        AscendC::PipeBarrier<PIPE_V>();

        // ---- Branch-dependent computation ----
        if (branchType == 0) {
            // Float bias / no bias: result = ((x * ws) * as) + bias
            AscendC::Mul(resultLocal, xFp32Local, wsTileLocal_, tileSize);       // x * ws
            AscendC::Mul(resultLocal, resultLocal, asTileLocal, tileSize);        // * as
            AscendC::Add(resultLocal, resultLocal, biasTileLocal_, tileSize);     // + bias
        } else {
            // Int32 bias: result = ((x + bias) * ws) * as
            AscendC::Add(tmpLocal, xFp32Local, biasTileLocal_, tileSize);         // x + bias
            AscendC::Mul(resultLocal, tmpLocal, wsTileLocal_, tileSize);          // * ws
            AscendC::Mul(resultLocal, resultLocal, asTileLocal, tileSize);        // * as
        }

        // Cast fp32 → output dtype
        if constexpr (std::is_same_v<OutT, float>) {
            // yFp32Local already aliases yOutLocal_ (via ReinterpretCast)
            // resultLocal is the compute result; copy to yFp32Local
            AscendC::DataCopyExtParams copyParams{1,
                static_cast<uint32_t>(tileSize * sizeof(float)), 0, 0, 0};
            AscendC::DataCopy(yFp32Local_, resultLocal, copyParams);
        } else {
            AscendC::Cast(yOutLocal_, resultLocal, OutputRoundModeHelper<OutT>(), tileSize);
            AscendC::PipeBarrier<PIPE_V>();
        }

        xInQueue_.FreeTensor(xInLocal_);
        yOutQueue_.EnQue(yOutLocal_);
    }

    // =====================================================================
    // CopyOut: write output [validRows*N] to GM
    // =====================================================================
    __aicore__ inline void CopyOutY(int32_t rowStart, int32_t tileSize)
    {
        yOutLocal_ = yOutQueue_.DeQue<OutT>();
        StoreUbToGm(yGM_[static_cast<uint64_t>(rowStart) * N], yOutLocal_, static_cast<uint32_t>(tileSize));
        yOutQueue_.FreeTensor(yOutLocal_);
    }

    // =====================================================================
    // Process one tile
    // =====================================================================
    __aicore__ inline void ProcessTile(int32_t rowStart, int32_t validRows)
    {
        const int32_t tileSize = validRows * N;
        CopyInX(rowStart, tileSize);
        Compute(rowStart, validRows);
        CopyOutY(rowStart, tileSize);
    }

private:
    int32_t M = 0;
    int32_t N = 0;
    int32_t tileM = 0;
    int32_t totalLength = 0;
    int32_t branchType = 0;
    int32_t tileElems_ = 0;

    AscendC::TPipe pipe;
    AscendC::GlobalTensor<int32_t> xGM_;
    AscendC::GlobalTensor<T> wsGM_;
    AscendC::GlobalTensor<float> asGM_;
    AscendC::GlobalTensor<float> biasGM_;
    AscendC::GlobalTensor<OutT> yGM_;

    // TQue
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> xInQueue_;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> yOutQueue_;

    // TBuf: resident
    AscendC::TBuf<AscendC::TPosition::VECCALC> wsBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> wsTileBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> wsBroadcastTmpBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> biasBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> biasTileBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> biasBroadcastTmpBuf_;

    // TBuf: per-tile
    AscendC::TBuf<AscendC::TPosition::VECCALC> asBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> asTileBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> asBroadcastTmpBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> xFp32Buf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> resultBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBuf_;

    // TBuf: cast
    AscendC::TBuf<AscendC::TPosition::VECCALC> wsCastBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> xCastBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> yCastBuf_;

    // LocalTensor — resident
    AscendC::LocalTensor<T> wsInLocal_;
    AscendC::LocalTensor<float> ws1dFp32_;
    AscendC::LocalTensor<float> wsTileLocal_;
    AscendC::LocalTensor<uint8_t> wsBroadcastTmpLocal_;
    AscendC::LocalTensor<float> biasInLocal_;
    AscendC::LocalTensor<float> biasTileLocal_;
    AscendC::LocalTensor<uint8_t> biasBroadcastTmpLocal_;

    // LocalTensor — per invocation
    AscendC::LocalTensor<int32_t> xInLocal_;
    AscendC::LocalTensor<OutT> yOutLocal_;
    AscendC::LocalTensor<float> yFp32Local_;
};

// =========================================================================
// Dispatch: per weight_scale dtype
// =========================================================================

template <typename OutT>
__aicore__ inline void DispatchDequantBiasByWeightDtype(
    GM_ADDR x_gm, GM_ADDR ws_gm, GM_ADDR as_gm, GM_ADDR bias_gm, GM_ADDR y_gm,
    int32_t M, int32_t N, int32_t tileM, int32_t totalLength,
    int32_t branchType, int64_t weightDtypeFlag)
{
    if (weightDtypeFlag == 0) {  // fp32
        DequantBiasKernel<float, OutT> kernel;
        kernel.Init(x_gm, ws_gm, as_gm, bias_gm, y_gm, M, N, tileM, totalLength, branchType);
        kernel.Process();
    } else if (weightDtypeFlag == 1) {  // fp16
        DequantBiasKernel<half, OutT> kernel;
        kernel.Init(x_gm, ws_gm, as_gm, bias_gm, y_gm, M, N, tileM, totalLength, branchType);
        kernel.Process();
    } else {  // bf16
        DequantBiasKernel<bfloat16_t, OutT> kernel;
        kernel.Init(x_gm, ws_gm, as_gm, bias_gm, y_gm, M, N, tileM, totalLength, branchType);
        kernel.Process();
    }
}

// =========================================================================
// Kernel entry points
// =========================================================================
// weightDtypeFlag: 0=fp32, 1=fp16, 2=bf16
// We create separate entries for fp16 and bf16 output types.

extern "C" __global__ __aicore__ void dequant_bias(
    GM_ADDR x_gm, GM_ADDR ws_gm, GM_ADDR as_gm, GM_ADDR bias_gm, GM_ADDR y_gm,
    int32_t M, int32_t N, int32_t tileM, int32_t totalLength,
    int32_t branchType, int64_t weightDtypeFlag, int64_t outputDtypeFlag)
{
    if (outputDtypeFlag == 0) {  // fp16 output
        DispatchDequantBiasByWeightDtype<half>(
            x_gm, ws_gm, as_gm, bias_gm, y_gm,
            M, N, tileM, totalLength, branchType, weightDtypeFlag);
    } else {  // bf16 output
        DispatchDequantBiasByWeightDtype<bfloat16_t>(
            x_gm, ws_gm, as_gm, bias_gm, y_gm,
            M, N, tileM, totalLength, branchType, weightDtypeFlag);
    }
}
