// DequantBias Host — tiling + kernel launch via EXEC_KERNEL_CMD

#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"
#include "aclrtlaunch_dequant_bias.h"

#include <algorithm>
#include <cstdint>

namespace ascend_kernel {

// bufferCoefficient: per-element UB usage estimate for tileM * N computation
// See design docs for breakdown; includes TQue + TBuf + cast buffers
constexpr int32_t kBufferCoefficient = 44;

at::Tensor dequant_bias(
    const at::Tensor& x,
    const at::Tensor& weight_scale,
    const at::Tensor& activate_scale,
    const at::Tensor& bias,
    int64_t branch_type,
    int64_t weight_dtype_flag,
    int64_t output_dtype_flag)
{
    // --- Input validation ---
    TORCH_CHECK(x.dim() == 2, "x must be 2D");
    TORCH_CHECK(x.scalar_type() == at::kInt, "x must be int32");
    TORCH_CHECK(weight_scale.dim() == 1, "weight_scale must be 1D");
    TORCH_CHECK(activate_scale.dim() == 1, "activate_scale must be 1D");
    TORCH_CHECK(bias.dim() == 1, "bias must be 1D");

    int64_t M = x.size(0);
    int64_t N = x.size(1);
    TORCH_CHECK(weight_scale.size(0) == N, "weight_scale size mismatch");
    TORCH_CHECK(activate_scale.size(0) == M, "activate_scale size mismatch");
    TORCH_CHECK(bias.size(0) == N, "bias size mismatch");

    // --- Platform info ---
    auto ascendc_platform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int64_t coreNum = static_cast<int64_t>(ascendc_platform->GetCoreNumAiv());
    uint64_t ubSize = 0;
    ascendc_platform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);

    // --- Compute tileM from UB capacity ---
    int64_t intN = N;
    int64_t maxTileM = static_cast<int64_t>(ubSize) / (kBufferCoefficient * intN * 4);
    if (maxTileM < 1) maxTileM = 1;
    if (maxTileM > 256) maxTileM = 256;
    int64_t tileM = maxTileM;

    // --- Block tiling ---
    int64_t totalLength = (M + tileM - 1) / tileM;
    int64_t blockDim = std::min(coreNum, totalLength);

    // --- Create output tensor ---
    at::ScalarType out_dtype;
    if (output_dtype_flag == 1) {
        out_dtype = at::kBFloat16;
    } else {
        out_dtype = at::kHalf;
    }
    auto y = at::empty({M, N}, x.options().dtype(out_dtype));

    // --- EXEC_KERNEL_CMD: all args must be lvalues ---
    int32_t mVal = static_cast<int32_t>(M);
    int32_t nVal = static_cast<int32_t>(N);
    int32_t tileMVal = static_cast<int32_t>(tileM);
    int32_t totalLengthVal = static_cast<int32_t>(totalLength);
    int32_t branchTypeVal = static_cast<int32_t>(branch_type);

    EXEC_KERNEL_CMD(dequant_bias, blockDim,
        x, weight_scale, activate_scale, bias, y,
        mVal, nVal, tileMVal, totalLengthVal,
        branchTypeVal, weight_dtype_flag, output_dtype_flag);

    return y;
}

}  // namespace ascend_kernel
