// DequantBias AscendC kernel — simplified with TQue double-buffer approach

#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 2;

template <typename T>
__aicore__ inline void LoadPad(
    AscendC::LocalTensor<T> &dst,
    AscendC::GlobalTensor<T> src,
    uint32_t count)
{
    AscendC::DataCopyExtParams cp{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPadExtParams<T> pp{true, 0, 0, static_cast<T>(0)};
    AscendC::DataCopyPad(dst, src, cp, pp);
}

template <typename T>
__aicore__ inline void StorePad(
    AscendC::GlobalTensor<T> dst,
    AscendC::LocalTensor<T> &src,
    uint32_t count)
{
    AscendC::DataCopyExtParams cp{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPad(dst, src, cp);
}

template <typename T, typename OutT>
class DequantBiasKernel {
public:
    __aicore__ inline void Init(
        GM_ADDR x_gm, GM_ADDR ws_gm, GM_ADDR as_gm, GM_ADDR bias_gm, GM_ADDR y_gm,
        int32_t M, int32_t N, int32_t tileM, int32_t totalLength,
        int32_t branchType)
    {
        this->M = M; this->N = N; this->tileM = tileM;
        this->totalLength = totalLength; this->branchType = branchType;

        xGM_.SetGlobalBuffer(reinterpret_cast<__gm__ int32_t *>(x_gm), static_cast<uint64_t>(M) * N);
        wsGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(ws_gm), N);
        asGM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(as_gm), M);
        biasGM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(bias_gm), N);
        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ OutT *>(y_gm), static_cast<uint64_t>(M) * N);

        tileElems_ = tileM * N;
        pipe.InitBuffer(xInQueue_, BUFFER_NUM, tileElems_ * sizeof(int32_t));
        pipe.InitBuffer(yOutQueue_, BUFFER_NUM, tileElems_ * sizeof(OutT));
        pipe.InitBuffer(wsUB_, N * sizeof(float));
        pipe.InitBuffer(biasUB_, N * sizeof(float));
        pipe.InitBuffer(xFp32UB_, tileElems_ * sizeof(float));
        pipe.InitBuffer(resUB_, tileElems_ * sizeof(float));
        pipe.InitBuffer(tmpUB_, tileElems_ * sizeof(float));
    }

    __aicore__ inline void Process()
    {
        if ASCEND_IS_AIV {
            // Load resident ws and bias once
            PipeBarrier<PIPE_ALL>();
            auto wsFp32 = wsUB_.Get<float>();
            if constexpr (std::is_same_v<T, float>) {
                auto wsT = wsFp32.template ReinterpretCast<T>();
                LoadPad(wsT, wsGM_, N);
            } else {
                AscendC::TBuf<AscendC::TPosition::VECCALC> wsbuf;
                pipe.InitBuffer(wsbuf, N * sizeof(T));
                auto wsLoad = wsbuf.Get<T>();
                LoadPad(wsLoad, wsGM_, N);
                PipeBarrier<PIPE_MTE2>();
                PipeBarrier<PIPE_ALL>();
                Cast(wsFp32, wsLoad, AscendC::RoundMode::CAST_NONE, N);
            }
            PipeBarrier<PIPE_MTE2>();
            PipeBarrier<PIPE_ALL>();

            auto biasFp32 = biasUB_.Get<float>();
            LoadPad(biasFp32, biasGM_, N);
            PipeBarrier<PIPE_MTE2>();
            PipeBarrier<PIPE_ALL>();

            const int coreIdx = GetBlockIdx();
            const int subBN = GetSubBlockNum();
            const int subBI = GetSubBlockIdx();
            for (int32_t ti = coreIdx; ti < totalLength; ti += GetBlockNum()) {
                int32_t rs = ti * tileM;
                int32_t re = rs + tileM;
                if (re > M) re = M;
                int32_t nr = re - rs;
                int32_t rps = (nr + subBN - 1) / subBN;
                int32_t rs2 = rs + subBI * rps;
                int32_t re2 = rs2 + rps;
                if (re2 > re) re2 = re;
                int32_t vr = re2 - rs2;
                if (vr <= 0) continue;
                int32_t ts = vr * N;

                // CopyIn: load x[vr, N] int32
                xInLocal_ = xInQueue_.AllocTensor<int32_t>();
                LoadPad(xInLocal_, xGM_[static_cast<uint64_t>(rs2) * N], ts);
                xInQueue_.EnQue(xInLocal_);

                // Alloc output
                yOutLocal_ = yOutQueue_.AllocTensor<OutT>();

                // DeQue input
                xInLocal_ = xInQueue_.DeQue<int32_t>();

                // Cast int32→fp32
                auto xFp32 = xFp32UB_.Get<float>();
                Cast(xFp32, xInLocal_, AscendC::RoundMode::CAST_NONE, ts);
                PipeBarrier<PIPE_V>();

                xInQueue_.FreeTensor(xInLocal_);

                // Get activate_scale scalar
                float asVal = asGM_.GetValue(rs2);

                auto res = resUB_.Get<float>();

                if (branchType == 0) {
                    Mul(res, xFp32, wsFp32, ts);
                    Muls(res, res, asVal, ts);
                    Add(res, res, biasFp32, ts);
                } else {
                    auto tmp = tmpUB_.Get<float>();
                    Add(tmp, xFp32, biasFp32, ts);
                    Mul(res, tmp, wsFp32, ts);
                    Muls(res, res, asVal, ts);
                }

                // Cast fp32→output, write back
                if constexpr (std::is_same_v<OutT, float>) {
                    auto yOut = res.template ReinterpretCast<OutT>();
                    StorePad(yGM_[static_cast<uint64_t>(rs2) * N], yOut, ts);
                } else {
                    auto yOut = yOutLocal_;
                    Cast(yOut, res, AscendC::RoundMode::CAST_NONE, ts);
                    PipeBarrier<PIPE_V>();
                    StorePad(yGM_[static_cast<uint64_t>(rs2) * N], yOut, ts);
                }

                yOutQueue_.EnQue(yOutLocal_);
                yOutLocal_ = yOutQueue_.DeQue<OutT>();
                yOutQueue_.FreeTensor(yOutLocal_);
            }
        }
    }

private:
    int32_t M = 0, N = 0, tileM = 0, totalLength = 0, branchType = 0, tileElems_ = 0;
    AscendC::TPipe pipe;
    AscendC::GlobalTensor<int32_t> xGM_;
    AscendC::GlobalTensor<T> wsGM_;
    AscendC::GlobalTensor<float> asGM_;
    AscendC::GlobalTensor<float> biasGM_;
    AscendC::GlobalTensor<OutT> yGM_;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> xInQueue_;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> yOutQueue_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> wsUB_, biasUB_, xFp32UB_, resUB_, tmpUB_;
    AscendC::LocalTensor<int32_t> xInLocal_;
    AscendC::LocalTensor<OutT> yOutLocal_;
};

template <typename OutT>
__aicore__ inline void Dispatch(
    GM_ADDR x, GM_ADDR ws, GM_ADDR as, GM_ADDR b, GM_ADDR y,
    int32_t M, int32_t N, int32_t tM, int32_t tL,
    int32_t bT, int64_t wdf)
{
    if (wdf == 0) { DequantBiasKernel<float, OutT> k; k.Init(x,ws,as,b,y,M,N,tM,tL,bT); k.Process(); }
    else if (wdf == 1) { DequantBiasKernel<half, OutT> k; k.Init(x,ws,as,b,y,M,N,tM,tL,bT); k.Process(); }
    else { DequantBiasKernel<bfloat16_t, OutT> k; k.Init(x,ws,as,b,y,M,N,tM,tL,bT); k.Process(); }
}

extern "C" __global__ __aicore__ void dequant_bias(
    GM_ADDR x, GM_ADDR ws, GM_ADDR as, GM_ADDR b, GM_ADDR y,
    int32_t M, int32_t N, int32_t tM, int32_t tL,
    int32_t bT, int64_t wdf, int64_t odf)
{
    if (odf == 0) Dispatch<half>(x,ws,as,b,y,M,N,tM,tL,bT,wdf);
    else Dispatch<bfloat16_t>(x,ws,as,b,y,M,N,tM,tL,bT,wdf);
}
