 */

// DequantBias AscendC kernel — row-by-row vector processing

#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 1;

// =========================================================================
// Data movement helpers
// =========================================================================

template <typename T>
__aicore__ inline void LoadGmToUb(
    AscendC::LocalTensor<T> &dst,
    AscendC::GlobalTensor<T> src,
    uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPadExtParams<T> padParams{true, 0, 0, static_cast<T>(0)};
    AscendC::DataCopyPad(dst, src, copyParams, padParams);
}

template <typename T>
__aicore__ inline void StoreUbToGm(
    AscendC::GlobalTensor<T> dst,
    AscendC::LocalTensor<T> &src,
    uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPad(dst, src, copyParams);
}

// =========================================================================
// Main kernel class — row-by-row approach
// T  = weight_scale dtype, OutT = output dtype
// =========================================================================

template <typename T, typename OutT>
class DequantBiasKernel {
public:
    __aicore__ inline void Init(
        GM_ADDR x_gm, GM_ADDR ws_gm, GM_ADDR as_gm, GM_ADDR bias_gm, GM_ADDR y_gm,
        int32_t M, int32_t N, int32_t tileM, int32_t totalLength,
        int32_t branchType)
    {
        this->M = M; this->N = N; this->tileM = tileM;
        this->totalLength = totalLength; this->branchType = branchType;

        xGM_.SetGlobalBuffer(reinterpret_cast<__gm__ int32_t *>(x_gm), static_cast<uint64_t>(M) * N);
        wsGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(ws_gm), N);
        asGM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(as_gm), M);
        biasGM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(bias_gm), N);
        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ OutT *>(y_gm), static_cast<uint64_t>(M) * N);

        // Per-row buffers
        pipe.InitBuffer(xRowInt32Buf_, N * sizeof(int32_t));
        pipe.InitBuffer(xRowFp32Buf_, N * sizeof(float));
        pipe.InitBuffer(resultBuf_, N * sizeof(float));
        pipe.InitBuffer(tmpBuf_, N * sizeof(float));
        if constexpr (!std::is_same_v<OutT, float>) {
            pipe.InitBuffer(yRowOutBuf_, N * sizeof(OutT));
        }

        // Resident buffers
        pipe.InitBuffer(wsBuf_, N * sizeof(float));
        pipe.InitBuffer(biasBuf_, N * sizeof(float));
    }

    __aicore__ inline void LoadResidentWeights()
    {
        wsResident_ = wsBuf_.Get<float>();
        if constexpr (std::is_same_v<T, float>) {
            // Direct load as float
            auto wsTmp = wsResident_.template ReinterpretCast<T>();
            LoadGmToUb(wsTmp, wsGM_, static_cast<uint32_t>(N));
        } else {
            // Load as T, cast to float
            AscendC::TBuf<AscendC::TPosition::VECCALC> wsLoadTmp;
            pipe.InitBuffer(wsLoadTmp, N * sizeof(T));
            auto wsLoad = wsLoadTmp.Get<T>();
            LoadGmToUb(wsLoad, wsGM_, static_cast<uint32_t>(N));
            AscendC::PipeBarrier<PIPE_MTE2>();
            AscendC::PipeBarrier<PIPE_ALL>();
            AscendC::Cast(wsResident_, wsLoad, AscendC::RoundMode::CAST_NONE, N);
        }
        AscendC::PipeBarrier<PIPE_MTE2>();
        AscendC::PipeBarrier<PIPE_ALL>();

        biasResident_ = biasBuf_.Get<float>();
        LoadGmToUb(biasResident_, biasGM_, static_cast<uint32_t>(N));
        AscendC::PipeBarrier<PIPE_MTE2>();
        AscendC::PipeBarrier<PIPE_ALL>();
    }

    __aicore__ inline void Process()
    {
        if ASCEND_IS_AIV {
            LoadResidentWeights();

            const int coreIdx = AscendC::GetBlockIdx();
            const int subBlockNum = AscendC::GetSubBlockNum();
            const int subBlockIdx = AscendC::GetSubBlockIdx();

            for (int32_t tileIdx = coreIdx; tileIdx < totalLength;
                 tileIdx += AscendC::GetBlockNum()) {
                int32_t rowStart = tileIdx * tileM;
                int32_t rowEnd = rowStart + tileM;
                if (rowEnd > M) rowEnd = M;
                int32_t totalRows = rowEnd - rowStart;
                int32_t rowsPerSub = (totalRows + subBlockNum - 1) / subBlockNum;
                int32_t subStart = rowStart + subBlockIdx * rowsPerSub;
                int32_t subEnd = subStart + rowsPerSub;
                if (subEnd > rowEnd) subEnd = rowEnd;

                for (int32_t row = subStart; row < subEnd; ++row) {
                    ProcessRow(row);
                }
            }
        }
    }

private:
    __aicore__ inline void ProcessRow(int32_t row)
    {
        // Load x[row, :] int32 → cast to fp32
        auto xInt32 = xRowInt32Buf_.Get<int32_t>();
        LoadGmToUb(xInt32, xGM_[static_cast<uint64_t>(row) * N], static_cast<uint32_t>(N));
        AscendC::PipeBarrier<PIPE_MTE2>();
        AscendC::PipeBarrier<PIPE_ALL>();

        auto xFp32 = xRowFp32Buf_.Get<float>();
        AscendC::Cast(xFp32, xInt32, AscendC::RoundMode::CAST_NONE, N);
        AscendC::PipeBarrier<PIPE_V>();

        auto result = resultBuf_.Get<float>();

        // Get activate_scale[row] scalar
        float asVal = asGM_.GetValue(row);

        if (branchType == 0) {
            // Float bias: result = ((x * ws) * as) + bias
            AscendC::Mul(result, xFp32, wsResident_, N);
            AscendC::Muls(result, result, asVal, N);
            AscendC::Add(result, result, biasResident_, N);
        } else {
            // Int32 bias: result = ((x + bias) * ws) * as
            auto tmp = tmpBuf_.Get<float>();
            AscendC::Add(tmp, xFp32, biasResident_, N);
            AscendC::Mul(result, tmp, wsResident_, N);
            AscendC::Muls(result, result, asVal, N);
        }

        // Cast fp32 → output dtype, write back
        if constexpr (std::is_same_v<OutT, float>) {
            auto yOut = result.template ReinterpretCast<OutT>();
            StoreUbToGm(yGM_[static_cast<uint64_t>(row) * N], yOut, static_cast<uint32_t>(N));
        } else {
            auto yOut = yRowOutBuf_.Get<OutT>();
            AscendC::Cast(yOut, result, AscendC::RoundMode::CAST_NONE, N);
            AscendC::PipeBarrier<PIPE_V>();
            StoreUbToGm(yGM_[static_cast<uint64_t>(row) * N], yOut, static_cast<uint32_t>(N));
        }
    }

    int32_t M = 0, N = 0, tileM = 0, totalLength = 0, branchType = 0;
    AscendC::TPipe pipe;

    AscendC::GlobalTensor<int32_t> xGM_;
    AscendC::GlobalTensor<T> wsGM_;
    AscendC::GlobalTensor<float> asGM_;
    AscendC::GlobalTensor<float> biasGM_;
    AscendC::GlobalTensor<OutT> yGM_;

    AscendC::TBuf<AscendC::TPosition::VECCALC> xRowInt32Buf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> xRowFp32Buf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> resultBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> yRowOutBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> wsBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> biasBuf_;

    AscendC::LocalTensor<float> wsResident_;
    AscendC::LocalTensor<float> biasResident_;
};

// =========================================================================
// Dispatch functions
// =========================================================================

template <typename OutT>
__aicore__ inline void DispatchByWeightDtype(
    GM_ADDR x, GM_ADDR ws, GM_ADDR as, GM_ADDR b, GM_ADDR y,
    int32_t M, int32_t N, int32_t tM, int32_t tL,
    int32_t bT, int64_t wdf)
{
    if (wdf == 0) {
        DequantBiasKernel<float, OutT> k;
        k.Init(x, ws, as, b, y, M, N, tM, tL, bT); k.Process();
    } else if (wdf == 1) {
        DequantBiasKernel<half, OutT> k;
        k.Init(x, ws, as, b, y, M, N, tM, tL, bT); k.Process();
    } else {
        DequantBiasKernel<bfloat16_t, OutT> k;
        k.Init(x, ws, as, b, y, M, N, tM, tL, bT); k.Process();
    }
}

extern "C" __global__ __aicore__ void dequant_bias(
    GM_ADDR x, GM_ADDR ws, GM_ADDR as, GM_ADDR b, GM_ADDR y,
    int32_t M, int32_t N, int32_t tM, int32_t tL,
    int32_t bT, int64_t wdf, int64_t odf)
{
    if (odf == 0) {
        DispatchByWeightDtype<half>(x, ws, as, b, y, M, N, tM, tL, bT, wdf);
    } else {
        DispatchByWeightDtype<bfloat16_t>(x, ws, as, b, y, M, N, tM, tL, bT, wdf);
    }
}
