// DequantBias AscendC kernel — following rms_norm pattern closely

#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 1;

template <typename T>
__aicore__ inline void LoadPad(
    AscendC::LocalTensor<T> &dst,
    AscendC::GlobalTensor<T> src,
    uint32_t count)
{
    AscendC::DataCopyExtParams cp{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPadExtParams<T> pp{true, 0, 0, static_cast<T>(0)};
    AscendC::DataCopyPad(dst, src, cp, pp);
}

template <typename T>
__aicore__ inline void StorePad(
    AscendC::GlobalTensor<T> dst,
    AscendC::LocalTensor<T> &src,
    uint32_t count)
{
    AscendC::DataCopyExtParams cp{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPad(dst, src, cp);
}

// =========================================================================
// ProcessRow — do one row compuattion using resident weight_scale and bias
// =========================================================================

template <typename T, typename OutT>
__aicore__ inline void ProcessRow(
    int32_t row, int32_t N, int32_t branchType,
    AscendC::GlobalTensor<int32_t> &xGM,
    AscendC::GlobalTensor<float> &asGM,
    AscendC::GlobalTensor<OutT> &yGM,
    AscendC::LocalTensor<float> &wsResident,
    AscendC::LocalTensor<float> &biasResident,
    AscendC::TBuf<AscendC::TPosition::VECCALC> &xInt32Buf,
    AscendC::TBuf<AscendC::TPosition::VECCALC> &xFp32Buf,
    AscendC::TBuf<AscendC::TPosition::VECCALC> &resBuf,
    AscendC::TBuf<AscendC::TPosition::VECCALC> &tmpBuf,
    AscendC::TBuf<AscendC::TPosition::VECCALC> &yBuf)
{
    // Load x[row,:] int32
    auto xi = xInt32Buf.Get<int32_t>();
    LoadPad(xi, xGM[static_cast<uint64_t>(row) * N], N);
    AscendC::PipeBarrier<PIPE_MTE2>();
    AscendC::PipeBarrier<PIPE_ALL>();

    // Cast to fp32
    auto xf = xFp32Buf.Get<float>();
    AscendC::Cast(xf, xi, AscendC::RoundMode::CAST_NONE, N);
    AscendC::PipeBarrier<PIPE_V>();

    auto res = resBuf.Get<float>();

    // Get activate_scale[row]
    float asVal = asGM.GetValue(row);

    if (branchType == 0) {
        AscendC::Mul(res, xf, wsResident, N);
        AscendC::Muls(res, res, asVal, N);
        AscendC::Add(res, res, biasResident, N);
    } else {
        auto tm = tmpBuf.Get<float>();
        AscendC::Add(tm, xf, biasResident, N);
        AscendC::Mul(res, tm, wsResident, N);
        AscendC::Muls(res, res, asVal, N);
    }

    // Write output
    if constexpr (std::is_same_v<OutT, float>) {
        auto yo = res.template ReinterpretCast<OutT>();
        StorePad(yGM[static_cast<uint64_t>(row) * N], yo, N);
    } else {
        auto yo = yBuf.Get<OutT>();
        AscendC::Cast(yo, res, AscendC::RoundMode::CAST_NONE, N);
        AscendC::PipeBarrier<PIPE_V>();
        StorePad(yGM[static_cast<uint64_t>(row) * N], yo, N);
    }
}

// =========================================================================
// Kernel entry — follows rms_norm pattern
// =========================================================================

template <typename T, typename OutT>
__aicore__ inline void DequantBiasEntry(
    GM_ADDR x_gm, GM_ADDR ws_gm, GM_ADDR as_gm, GM_ADDR bias_gm, GM_ADDR y_gm,
    int32_t M, int32_t N, int32_t tileM, int32_t totalLength,
    int32_t branchType)
{
    if ASCEND_IS_AIV {
        AscendC::GlobalTensor<int32_t> xGM;
        AscendC::GlobalTensor<T> wsGM;
        AscendC::GlobalTensor<float> asGM;
        AscendC::GlobalTensor<float> biasGM;
        AscendC::GlobalTensor<OutT> yGM;
        xGM.SetGlobalBuffer(reinterpret_cast<__gm__ int32_t *>(x_gm), static_cast<uint64_t>(M) * N);
        wsGM.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(ws_gm), N);
        asGM.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(as_gm), M);
        biasGM.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(bias_gm), N);
        yGM.SetGlobalBuffer(reinterpret_cast<__gm__ OutT *>(y_gm), static_cast<uint64_t>(M) * N);

        AscendC::TPipe pipe;

        // Per-row buffers
        AscendC::TBuf<AscendC::TPosition::VECCALC> xIBuf, xFBuf, rBuf, tBuf, yBuf;
        pipe.InitBuffer(xIBuf, N * sizeof(int32_t));
        pipe.InitBuffer(xFBuf, N * sizeof(float));
        pipe.InitBuffer(rBuf, N * sizeof(float));
        pipe.InitBuffer(tBuf, N * sizeof(float));
        if constexpr (!std::is_same_v<OutT, float>) {
            pipe.InitBuffer(yBuf, N * sizeof(OutT));
        }

        // Resident weight_scale buffer
        AscendC::TBuf<AscendC::TPosition::VECCALC> wsBuf;
        pipe.InitBuffer(wsBuf, N * sizeof(float));
        AscendC::LocalTensor<float> wsR = wsBuf.Get<float>();

        if constexpr (std::is_same_v<T, float>) {
            auto wsT = wsR.template ReinterpretCast<T>();
            LoadPad(wsT, wsGM, N);
        } else {
            AscendC::TBuf<AscendC::TPosition::VECCALC> wsLoad;
            pipe.InitBuffer(wsLoad, N * sizeof(T));
            auto wl = wsLoad.Get<T>();
            LoadPad(wl, wsGM, N);
            AscendC::PipeBarrier<PIPE_MTE2>();
            AscendC::PipeBarrier<PIPE_ALL>();
            AscendC::Cast(wsR, wl, AscendC::RoundMode::CAST_NONE, N);
        }
        AscendC::PipeBarrier<PIPE_MTE2>();
        AscendC::PipeBarrier<PIPE_ALL>();

        // Resident bias buffer
        AscendC::TBuf<AscendC::TPosition::VECCALC> biasBuf;
        pipe.InitBuffer(biasBuf, N * sizeof(float));
        AscendC::LocalTensor<float> biasR = biasBuf.Get<float>();
        LoadPad(biasR, biasGM, N);
        AscendC::PipeBarrier<PIPE_MTE2>();
        AscendC::PipeBarrier<PIPE_ALL>();

        // Work distribution
        const int coreIdx = AscendC::GetBlockIdx();
        const int subBN = AscendC::GetSubBlockNum();
        const int subBI = AscendC::GetSubBlockIdx();
        for (int32_t ti = coreIdx; ti < totalLength; ti += AscendC::GetBlockNum()) {
            int32_t rs = ti * tileM;
            int32_t re = rs + tileM;
            if (re > M) re = M;
            int32_t nr = re - rs;
            int32_t rps = (nr + subBN - 1) / subBN;
            int32_t rs2 = rs + subBI * rps;
            int32_t re2 = rs2 + rps;
            if (re2 > re) re2 = re;
            for (int32_t row = rs2; row < re2; ++row) {
                ProcessRow<T, OutT>(row, N, branchType, xGM, asGM, yGM,
                    wsR, biasR, xIBuf, xFBuf, rBuf, tBuf, yBuf);
            }
        }
    }
}

// =========================================================================
// Dispatch
// =========================================================================

template <typename OutT>
__aicore__ inline void DispatchWD(
    GM_ADDR x, GM_ADDR ws, GM_ADDR as, GM_ADDR b, GM_ADDR y,
    int32_t M, int32_t N, int32_t tM, int32_t tL,
    int32_t bT, int64_t wdf)
{
    if (wdf == 0)      DequantBiasEntry<float, OutT>(x, ws, as, b, y, M, N, tM, tL, bT);
    else if (wdf == 1) DequantBiasEntry<half, OutT>(x, ws, as, b, y, M, N, tM, tL, bT);
    else               DequantBiasEntry<bfloat16_t, OutT>(x, ws, as, b, y, M, N, tM, tL, bT);
}

extern "C" __global__ __aicore__ void dequant_bias(
    GM_ADDR x, GM_ADDR ws, GM_ADDR as, GM_ADDR b, GM_ADDR y,
    int32_t M, int32_t N, int32_t tM, int32_t tL,
    int32_t bT, int64_t wdf, int64_t odf)
{
    if (odf == 0) DispatchWD<half>(x, ws, as, b, y, M, N, tM, tL, bT, wdf);
    else          DispatchWD<bfloat16_t>(x, ws, as, b, y, M, N, tM, tL, bT, wdf);
}
