// DequantBias AscendC kernel
// Multi-input fusion: int32 dequant + weight_scale + optional bias + activate_scale.

#include "kernel_operator.h"

// =========================================================================
// Data movement helpers
// =========================================================================

template <typename T>
__aicore__ inline void LoadPad(
    AscendC::LocalTensor<T> &dst,
    AscendC::GlobalTensor<T> src,
    uint32_t count)
{
    AscendC::DataCopyExtParams cp{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPadExtParams<T> pp{true, 0, 0, static_cast<T>(0)};
    AscendC::DataCopyPad(dst, src, cp, pp);
}

template <typename T>
__aicore__ inline void StorePad(
    AscendC::GlobalTensor<T> dst,
    AscendC::LocalTensor<T> &src,
    uint32_t count)
{
    AscendC::DataCopyExtParams cp{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPad(dst, src, cp);
}

// =========================================================================
// Main kernel entry — follows mini kernel pattern that works
// =========================================================================
// T = weight_scale input dtype, OutT = output dtype

template <typename T, typename OutT>
__aicore__ inline void DequantBiasKernel(
    GM_ADDR x_gm, GM_ADDR ws_gm, GM_ADDR as_gm, GM_ADDR bias_gm, GM_ADDR y_gm,
    int32_t M, int32_t N, int32_t tileM, int32_t totalLength,
    int32_t branchType)
{
    if ASCEND_IS_AIV {
        // Set up GlobalTensors
        AscendC::GlobalTensor<int32_t> xGM;
        AscendC::GlobalTensor<T> wsGM;
        AscendC::GlobalTensor<float> asGM;
        AscendC::GlobalTensor<float> biasGM;
        AscendC::GlobalTensor<OutT> yGM;
        xGM.SetGlobalBuffer(reinterpret_cast<__gm__ int32_t *>(x_gm), static_cast<uint64_t>(M) * N);
        wsGM.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(ws_gm), N);
        asGM.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(as_gm), M);
        biasGM.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(bias_gm), N);
        yGM.SetGlobalBuffer(reinterpret_cast<__gm__ OutT *>(y_gm), static_cast<uint64_t>(M) * N);

        AscendC::TPipe pipe;

        // Per-row compute buffers
        AscendC::TBuf<AscendC::TPosition::VECCALC> xInt32Buf, xFp32Buf, resBuf, tmpBuf, yOutBuf;
        pipe.InitBuffer(xInt32Buf, N * sizeof(int32_t));
        pipe.InitBuffer(xFp32Buf, N * sizeof(float));
        pipe.InitBuffer(resBuf, N * sizeof(float));
        pipe.InitBuffer(tmpBuf, N * sizeof(float));
        if constexpr (!std::is_same_v<OutT, float>) {
            pipe.InitBuffer(yOutBuf, N * sizeof(OutT));
        }

        // ---- Load resident weight_scale [N] → float32 ----
        AscendC::TBuf<AscendC::TPosition::VECCALC> wsFp32Buf;
        pipe.InitBuffer(wsFp32Buf, N * sizeof(float));
        AscendC::LocalTensor<float> wsFp32 = wsFp32Buf.Get<float>();

        if constexpr (std::is_same_v<T, float>) {
            auto wsT = wsFp32.template ReinterpretCast<T>();
            LoadPad(wsT, wsGM, N);
        } else {
            AscendC::TBuf<AscendC::TPosition::VECCALC> wsLoadBuf;
            pipe.InitBuffer(wsLoadBuf, N * sizeof(T));
            auto wsLoad = wsLoadBuf.Get<T>();
            LoadPad(wsLoad, wsGM, N);
            AscendC::PipeBarrier<PIPE_MTE2>();
            AscendC::PipeBarrier<PIPE_ALL>();
            AscendC::Cast(wsFp32, wsLoad, AscendC::RoundMode::CAST_NONE, N);
        }
        AscendC::PipeBarrier<PIPE_MTE2>();
        AscendC::PipeBarrier<PIPE_ALL>();

        // ---- Load resident bias [N] → float32 (host already cast) ----
        AscendC::TBuf<AscendC::TPosition::VECCALC> biasFp32Buf;
        pipe.InitBuffer(biasFp32Buf, N * sizeof(float));
        AscendC::LocalTensor<float> biasFp32 = biasFp32Buf.Get<float>();
        LoadPad(biasFp32, biasGM, N);
        AscendC::PipeBarrier<PIPE_MTE2>();
        AscendC::PipeBarrier<PIPE_ALL>();

        // ---- Distribute rows across AIV sub-cores ----
        const int coreIdx = AscendC::GetBlockIdx();
        const int subBN = AscendC::GetSubBlockNum();
        const int subBI = AscendC::GetSubBlockIdx();

        for (int32_t ti = coreIdx; ti < totalLength; ti += AscendC::GetBlockNum()) {
            int32_t rs = ti * tileM;
            int32_t re = rs + tileM;
            if (re > M) re = M;
            int32_t nr = re - rs;
            int32_t rps = (nr + subBN - 1) / subBN;
            int32_t rs2 = rs + subBI * rps;
            int32_t re2 = rs2 + rps;
            if (re2 > re) re2 = re;

            for (int32_t row = rs2; row < re2; ++row) {
                // ---- Load x[row, :] int32 → cast to fp32 ----
                auto xi = xInt32Buf.Get<int32_t>();
                LoadPad(xi, xGM[static_cast<uint64_t>(row) * N], N);
                AscendC::PipeBarrier<PIPE_MTE2>();
                AscendC::PipeBarrier<PIPE_ALL>();

                auto xf = xFp32Buf.Get<float>();
                AscendC::Cast(xf, xi, AscendC::RoundMode::CAST_NONE, N);
                AscendC::PipeBarrier<PIPE_V>();

                auto res = resBuf.Get<float>();

                // Get activate_scale[row] (scalar)
                float asVal = asGM.GetValue(row);

                // ---- Branch-dependent computation ----
                if (branchType == 0) {
                    // Float bias / no bias: result = ((x * ws) * as) + bias
                    AscendC::Mul(res, xf, wsFp32, N);
                    AscendC::Muls(res, res, asVal, N);
                    AscendC::Add(res, res, biasFp32, N);
                } else {
                    // Int32 bias: result = ((x + bias) * ws) * as
                    auto tm = tmpBuf.Get<float>();
                    AscendC::Add(tm, xf, biasFp32, N);
                    AscendC::Mul(res, tm, wsFp32, N);
                    AscendC::Muls(res, res, asVal, N);
                }

                // ---- Cast fp32 → output dtype, write back ----
                if constexpr (std::is_same_v<OutT, float>) {
                    auto yo = res.template ReinterpretCast<OutT>();
                    StorePad(yGM[static_cast<uint64_t>(row) * N], yo, N);
                } else {
                    auto yo = yOutBuf.Get<OutT>();
                    AscendC::Cast(yo, res, AscendC::RoundMode::CAST_NONE, N);
                    AscendC::PipeBarrier<PIPE_V>();
                    StorePad(yGM[static_cast<uint64_t>(row) * N], yo, N);
                }
            }
        }
    }
}

// =========================================================================
// Dispatch — weight_scale dtype
// =========================================================================

template <typename OutT>
__aicore__ inline void DispatchByWeight(
    GM_ADDR x, GM_ADDR ws, GM_ADDR as, GM_ADDR b, GM_ADDR y,
    int32_t M, int32_t N, int32_t tM, int32_t tL,
    int32_t bT, int64_t wdf)
{
    if (wdf == 0)      DequantBiasKernel<float, OutT>(x, ws, as, b, y, M, N, tM, tL, bT);
    else if (wdf == 1) DequantBiasKernel<half, OutT>(x, ws, as, b, y, M, N, tM, tL, bT);
    else               DequantBiasKernel<bfloat16_t, OutT>(x, ws, as, b, y, M, N, tM, tL, bT);
}

