{
    if (odf == 0) DispatchByWeight<half>(x, ws, as, b, y, M, N, tM, tL, bT, wdf);
    else          DispatchByWeight<bfloat16_t>(x, ws, as, b, y, M, N, tM, tL, bT, wdf);
}
