// DequantBias AscendC kernel — full implementation

#include "kernel_operator.h"

extern "C" __global__ __aicore__ void dequant_bias(
    GM_ADDR x_gm, GM_ADDR ws_gm, GM_ADDR as_gm, GM_ADDR bias_gm, GM_ADDR y_gm,
    int32_t M, int32_t N, int32_t tileM, int32_t totalLength,
    int32_t branchType, int64_t wdf, int64_t odf)
{
    if ASCEND_IS_AIV {
        AscendC::GlobalTensor<int32_t> xG;
        AscendC::GlobalTensor<float> wsG;
        AscendC::GlobalTensor<float> asG;
        AscendC::GlobalTensor<float> biasG;

        xG.SetGlobalBuffer(reinterpret_cast<__gm__ int32_t *>(x_gm), static_cast<uint64_t>(M) * N);
        wsG.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(ws_gm), N);
        asG.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(as_gm), M);
        biasG.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(bias_gm), N);

        AscendC::TPipe pipe;

        // Resident ws + bias
        AscendC::TBuf<AscendC::TPosition::VECCALC> wsBuf, biasBuf;
        pipe.InitBuffer(wsBuf, N * sizeof(float));
        pipe.InitBuffer(biasBuf, N * sizeof(float));
        auto wsf = wsBuf.Get<float>();
        auto biasf = biasBuf.Get<float>();

        AscendC::DataCopyExtParams cpw{1, static_cast<uint32_t>(N * sizeof(float)), 0, 0, 0};
        AscendC::DataCopyPadExtParams<float> ppw{true, 0, 0, 0.0f};
        AscendC::DataCopyPad(wsf, wsG, cpw, ppw);
        AscendC::PipeBarrier<PIPE_MTE2>();
        AscendC::PipeBarrier<PIPE_ALL>();

        AscendC::DataCopyExtParams cpb{1, static_cast<uint32_t>(N * sizeof(float)), 0, 0, 0};
        AscendC::DataCopyPadExtParams<float> ppb{true, 0, 0, 0.0f};
        AscendC::DataCopyPad(biasf, biasG, cpb, ppb);
        AscendC::PipeBarrier<PIPE_MTE2>();
        AscendC::PipeBarrier<PIPE_ALL>();

        // Per-tile as buffer
        AscendC::TBuf<AscendC::TPosition::VECCALC> asTileBuf;
        pipe.InitBuffer(asTileBuf, tileM * sizeof(float));

        // Per-row buffers
        AscendC::TBuf<AscendC::TPosition::VECCALC> xBuf, fBuf, rBuf, tBuf;
        pipe.InitBuffer(xBuf, N * sizeof(int32_t));
        pipe.InitBuffer(fBuf, N * sizeof(float));
        pipe.InitBuffer(rBuf, N * sizeof(float));
        pipe.InitBuffer(tBuf, N * sizeof(float));

        // Output dtype handling
        if (odf == 0) {
            // fp16 output
            AscendC::GlobalTensor<half> yG;
            yG.SetGlobalBuffer(reinterpret_cast<__gm__ half *>(y_gm), static_cast<uint64_t>(M) * N);
            AscendC::TBuf<AscendC::TPosition::VECCALC> yBuf;
            pipe.InitBuffer(yBuf, N * sizeof(half));

            const int cid = AscendC::GetBlockIdx();
            const int sbn = AscendC::GetSubBlockNum();
            const int sbi = AscendC::GetSubBlockIdx();

            for (int32_t ti = cid; ti < totalLength; ti += AscendC::GetBlockNum()) {
                int32_t rs = ti * tileM, re = rs + tileM;
                if (re > M) re = M;
                int32_t nr = re - rs;
                int32_t rps = (nr + sbn - 1) / sbn;
                int32_t rs2 = rs + sbi * rps, re2 = rs2 + rps;
                if (re2 > re) re2 = re;

                // Load as tile
                auto asTile = asTileBuf.Get<float>();
                AscendC::DataCopyExtParams cpas{1, static_cast<uint32_t>(nr * sizeof(float)), 0, 0, 0};
                AscendC::DataCopyPadExtParams<float> ppas{true, 0, 0, 0.0f};
                AscendC::DataCopyPad(asTile, asG[rs], cpas, ppas);
                AscendC::PipeBarrier<PIPE_MTE2>();
                AscendC::PipeBarrier<PIPE_ALL>();

                for (int32_t row = rs2; row < re2; ++row) {
                    auto xi = xBuf.Get<int32_t>();
                    AscendC::DataCopyExtParams cp{1, static_cast<uint32_t>(N * sizeof(int32_t)), 0, 0, 0};
                    AscendC::DataCopyPadExtParams<int32_t> pp{true, 0, 0, 0};
                    AscendC::DataCopyPad(xi, xG[static_cast<uint64_t>(row) * N], cp, pp);
                    AscendC::PipeBarrier<PIPE_MTE2>();
                    AscendC::PipeBarrier<PIPE_ALL>();

                    auto xf = fBuf.Get<float>();
                    AscendC::Cast(xf, xi, AscendC::RoundMode::CAST_NONE, N);
                    AscendC::PipeBarrier<PIPE_V>();

                    float asVal = asTile.GetValue(row - rs);
                    auto res = rBuf.Get<float>();

                    if (branchType == 0) {
                        AscendC::Mul(res, xf, wsf, N);
                        AscendC::PipeBarrier<PIPE_V>();
                        AscendC::Muls(res, res, asVal, N);
                        AscendC::PipeBarrier<PIPE_V>();
                        AscendC::Add(res, res, biasf, N);
                        AscendC::PipeBarrier<PIPE_V>();
                    } else {
                        auto tm = tBuf.Get<float>();
                        AscendC::Add(tm, xf, biasf, N);
                        AscendC::PipeBarrier<PIPE_V>();
                        AscendC::Mul(res, tm, wsf, N);
                        AscendC::PipeBarrier<PIPE_V>();
                        AscendC::Muls(res, res, asVal, N);
                        AscendC::PipeBarrier<PIPE_V>();
                    }

                    auto yo = yBuf.Get<half>();
                    AscendC::Cast(yo, res, AscendC::RoundMode::CAST_NONE, N);
                    AscendC::PipeBarrier<PIPE_V>();

                    AscendC::DataCopyExtParams cp2{1, static_cast<uint32_t>(N * sizeof(half)), 0, 0, 0};
                    AscendC::DataCopyPad(yG[static_cast<uint64_t>(row) * N], yo, cp2);
                }
            }
        } else {
            // bf16 output
            AscendC::GlobalTensor<bfloat16_t> yG;
            yG.SetGlobalBuffer(reinterpret_cast<__gm__ bfloat16_t *>(y_gm), static_cast<uint64_t>(M) * N);
            AscendC::TBuf<AscendC::TPosition::VECCALC> yBuf;
            pipe.InitBuffer(yBuf, N * sizeof(bfloat16_t));

            const int cid = AscendC::GetBlockIdx();
            const int sbn = AscendC::GetSubBlockNum();
            const int sbi = AscendC::GetSubBlockIdx();

            for (int32_t ti = cid; ti < totalLength; ti += AscendC::GetBlockNum()) {
                int32_t rs = ti * tileM, re = rs + tileM;
                if (re > M) re = M;
                int32_t nr = re - rs;
                int32_t rps = (nr + sbn - 1) / sbn;
                int32_t rs2 = rs + sbi * rps, re2 = rs2 + rps;
                if (re2 > re) re2 = re;

                // Load as tile
                auto asTile = asTileBuf.Get<float>();
                AscendC::DataCopyExtParams cpas{1, static_cast<uint32_t>(nr * sizeof(float)), 0, 0, 0};
                AscendC::DataCopyPadExtParams<float> ppas{true, 0, 0, 0.0f};
                AscendC::DataCopyPad(asTile, asG[rs], cpas, ppas);
                AscendC::PipeBarrier<PIPE_MTE2>();
                AscendC::PipeBarrier<PIPE_ALL>();

                for (int32_t row = rs2; row < re2; ++row) {
                    auto xi = xBuf.Get<int32_t>();
                    AscendC::DataCopyExtParams cp{1, static_cast<uint32_t>(N * sizeof(int32_t)), 0, 0, 0};
                    AscendC::DataCopyPadExtParams<int32_t> pp{true, 0, 0, 0};
                    AscendC::DataCopyPad(xi, xG[static_cast<uint64_t>(row) * N], cp, pp);
                    AscendC::PipeBarrier<PIPE_MTE2>();
                    AscendC::PipeBarrier<PIPE_ALL>();

                    auto xf = fBuf.Get<float>();
                    AscendC::Cast(xf, xi, AscendC::RoundMode::CAST_NONE, N);
                    AscendC::PipeBarrier<PIPE_V>();

                    float asVal = asTile.GetValue(row - rs);
                    auto res = rBuf.Get<float>();

                    if (branchType == 0) {
                        AscendC::Mul(res, xf, wsf, N);
                        AscendC::PipeBarrier<PIPE_V>();
                        AscendC::Muls(res, res, asVal, N);
                        AscendC::PipeBarrier<PIPE_V>();
                        AscendC::Add(res, res, biasf, N);
                        AscendC::PipeBarrier<PIPE_V>();
                    } else {
                        auto tm = tBuf.Get<float>();
                        AscendC::Add(tm, xf, biasf, N);
                        AscendC::PipeBarrier<PIPE_V>();
                        AscendC::Mul(res, tm, wsf, N);
                        AscendC::PipeBarrier<PIPE_V>();
                        AscendC::Muls(res, res, asVal, N);
                        AscendC::PipeBarrier<PIPE_V>();
                    }

                    auto yo = yBuf.Get<bfloat16_t>();
                    AscendC::Cast(yo, res, AscendC::RoundMode::CAST_ROUND, N);
                    AscendC::PipeBarrier<PIPE_V>();

                    AscendC::DataCopyExtParams cp2{1, static_cast<uint32_t>(N * sizeof(bfloat16_t)), 0, 0, 0};
                    AscendC::DataCopyPad(yG[static_cast<uint64_t>(row) * N], yo, cp2);
                }
            }
        }
    }
}
